/// <summary>
/// Data Contract class for <c>SalesOrderLoadPlanningAid</c> SSRS report
/// </summary>
/// <remarks>
/// This is the Data Contract class for the <c>SalesOrderLoadPlanningAid</c> SSRS Report.The <c>METSalesOrderLoadPlanningAidContract</c> class is the data contract class for the <c>SalesOrderLoadPlanningAid</c>
/// SSRS report.
/// </remarks>
[
    DataContractAttribute
]
public class METSalesOrderLoadPlanningAidContract
{
    CustAccount                 custAccount;
    SalesShippingDateConfirmed  confirmedShipDateFrom;
    SalesShippingDateRequested  confirmedShipDateTo;
    METRoute                    routeID;
    InventLocationId            wareHouseId;    
    str                         recordList;
    InventSiteId                site;
    boolean                     exclCreditMgmt;
    METOrderExtractStatus       extractStatus;
    METOrderSplitGroup          orderSplitGroup;
    METSalesOrderTypeID         salesOrderTypeID;

}

